def _shuffled(seq: Sequence[str]) -> list[str]:
    """Deterministically shuffle"""
    shuf = []
    for el in range(len(seq)):
        shuf.append(seq[el])
    for i in range(len(seq)):
        r = random.randint(0, len(seq) - i - 1)
        shuf[i], shuf[r] = shuf[r], shuf[i]
    return shuf

