    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm with a per-item TTL value.

    """
    def decorator(func):
        cache = {}
        ttl_cache = {}
        misses = 0
        misses_ttl = {}
        hits = 0
        hits_ttl = {}

        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            key = args + (frozenset(kwargs.items()) if typed else None)
            nonlocal misses, hits
            now = timer()
            if key in cache:
                misses_ttl[key].append(now)
                if len(misses_ttl[key]) > maxsize:
                    oldest = min(misses_ttl[key])
                    oldest_index = misses_ttl[key].index(oldest)
                    del misses_ttl[key][oldest_index]

            if key not in ttl_cache or now - ttl_cache[key] > ttl:
                hit = func(*args, **kwargs)
                cache[key] = hit
                ttl_cache[key] = now
                misses += 1
                misses_ttl[key] = [now]
            else:
                hit = cache[key]
                hits += 1
                hits_ttl[key] = [now]

            return hit

        def info():
