        timer (function): Function used to generate the current time.
        typed (bool): If True, separate caches are maintained for different types of arguments.
    """

    def decorator(func):
        prefix = '.'
        if typed:
            prefix = prefix + str(type(func).__module__)

        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            key = prefix + '.' + str(args) + str(kwargs)
            now = timer()
            try:
                value, t0 = cache[key]
                if now - t0 < ttl:
                    return value
                else:
                    raise KeyError
            except KeyError:
                value = func(*args, **kwargs)
                cache[key] = (value, now)
                return value

        return wrapper

    return decorator

