    def decorator(func):
        cache = {}
        keys = []
        def wrapper(*args, **kwargs):
            key = ', '.join(map(repr, args))
            if typed and kwargs:
                key += ' ' + ', '.join('%s=%s' % (k, repr(v)) for k, v in kwargs.items())
            if key in cache:
                cached_value = cache[key]
                keys.remove(key)
                keys.append(key)
                return cached_value
            else:
