    def decorator(func):
        cache = {}
        counter = 0
        hits, misses = 0, 0

        def wrapper(*args, **kwargs):
            nonlocal hits, misses
            key = args
            if typed:
                key = [type(a) for a in key] + key
            count = func.__name__ + str(key)
            if count in cache:
                hits += 1
                cache[count][0] += 1
                return cache[count][1]
            misses += 1
            result = func(*args, **kwargs)
            cache[count] = [1, result]
            return result

        def info():
            return {'hits': hits, 'misses': misses, 'maxsize': maxsize}

