def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    seen = set()
    for cls in classes:
        if cls in seen:
            continue
        seen.add(cls)
        for b in _all_dicts(cls.__bases__, seen):
            yield b

def minimalBases(classes):
    def _all_dicts(bases, seen=None):
        """
        Yield each class in ``bases`` and each of their base classes.
        """
        if seen is None:
            seen = set()
        for cls in bases:
            if cls in seen:
                continue
            seen.add(cls)
            yield cls.__dict__
            for b in _all_dicts(cls.__bases__, seen):
                yield b

    def _compare_meta(c1, c2):
        if c1 == c2:
            return 0
        if c1 < c2:
            return 1
        return -1

    def _compare_name(c1, c2):
        if c1 == c2:
            return 0
        if c1 < c2:
            return 1
        return -1

    minimal = []
    for cls in classes:
        minimal_bases = [base for base in _all_dicts(cls.__bases__) if base not in minimal]
        minimal.append(cls)
        for base in minimal_bases:
            minimal.append(base)
    minimal.sort(key=lambda x: x.__dict__, reverse=True)
    return minimal

def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    if not classes:
        return classes
    classes = list(classes)
    while True:
        new_classes = []
        for cls in classes:
            if all(issubclass(cls, base) for base in classes if base is not cls):
                new_classes.append(cls)
        if len(new_classes) == len(classes):
            break
        classes = new_classes
    return tuple(classes)

