def to_csv(self, separator=",", header=None):
    with open(self.path, "w", encoding=self.encoding) as f:
        if header is not None:
            f.write(header + "\n")
        for point in self.points:
            coordinate = ", ".join([str(s) for s in point])
            value = ", ".join([v.to_str(separator) for v in point.values])
            f.write(f"{coordinate}: {value}\n")

def _get_err_indices(self, coord_name):
    err_indices = None
    for i, coord in enumerate(self.coordinates):
        if coord.name == coord_name:
            err_indices = i
            break

    if err_indices is None:
        raise ValueError(f"Coordinate '{coord_name}' not found in data.")

    return err_indices

def _get_err_indices(self, coord_name):
    """Get error indices corresponding to a coordinate."""
    self._update_err_coords()
    coord_var = self._err_coords[coord_name]
    err_vars = {v: np.random.rand(coord_var.size) for v in self.variables}
    return {v: err_vars[v][coord_var.values] for v in self.variables}

def _update_context(self, context):
    if "error" not in context:
        context["error"] = {}
    if "x" in self.data:
        if "x_low" not in context["error"]:
            context["error"]["x_low"] = {"index": 0}
        if "x_up" not in context["error"]:
            context["error"]["x_up"] = {"index": 1}
    if "y" in self.data:
        if "y_low" not in context["error"]:
            context["error"]["y_low"] = {"index": 2}
        if "y_up" not in context["error"]:
            context["error"]["y_up"] = {"index": 3}
    if "z" in self.data:
        if "z_low" not in context["error"]:
            context["error"]["z_low"] = {"index": 4}
        if "z_up" not in context["error"]:
            context["error"]["z_up"] = {"index": 5}

def integral(bins, edges):
    if isinstance(bins, np.ndarray):
        bins = list(bins)
    if isinstance(edges, np.ndarray):
        edges = list(edges)
    return np.array([(edges[i+1] - edges[i])
                     for i in range(len(edges)-1)])

