def generate_default_observer_schema_dict(manifest_dict, first_level=False):
    if first_level:
        observer_schema = {
            "apiVersion": manifest_dict["apiVersion"],
            "kind": manifest_dict["kind"],
            "metadata": manifest_dict["metadata"],
            "spec": {}
        }
        if "spec" in manifest_dict:
            observer_schema["spec"] = generate_default_observer_schema_dict(manifest_dict["spec"])
    else:
        observer_schema = {}
        for key, value in manifest_dict.items():
            if isinstance(value, list):
                observer_schema[key] = []
                for item in value:
                    if isinstance(item, dict):
                        observer_schema[key].append(generate_default_observer_schema_dict(item))
                    else:
                        observer_schema[key].append(None)
            elif isinstance(value, dict):
                observer_schema[key] = generate_default_observer_schema_dict(value)
            else:
                observer_schema[key] = None
    return observer_schema

def generate_default_observer_schema_dict(manifest_dict, first_level=False):
    if first_level:
        default_observer_schema = {}
        for k, v in manifest_dict.items():
            if not isinstance(v, (list, dict)):
                default_observer_schema[k] = None
            elif isinstance(v, list):
                default_observer_schema[k] = []
            else:
                default_observer_schema[k] = generate_default_observer_schema_dict(v, False)
        return default_observer_schema
    else:
        default_observer_schema = {}
        for k, v in manifest_dict.items():
            if not isinstance(v, (list, dict)):
                default_observer_schema[k] = None
            elif isinstance(v, list):
                default_observer_schema[k] = []
            else:
                default_observer_schema[k] = generate_default_observer_schema_dict(v, False)
        return default_observer_schema

def generate_default_observer_schema_dict(manifest_dict, first_level=False):
    if first_level:
        observer_schema = {
            "id": manifest_dict.get("metadata", {}).get("name"),
            "version": manifest_dict.get("metadata", {}).get("resourceVersion"),
            "category": manifest_dict.get("apiVersion").split("/")[0],
            "description": manifest_dict.get("metadata", {}).get("description"),
            "configuration": generate_default_observer_schema_dict(manifest_dict.get("spec", {}))
        }
    else:
        observer_schema = {}
        for key, value in manifest_dict.items():
            if isinstance(value, list) or isinstance(value, dict):
