    return observer_schema

def update_last_applied_manifest_list_from_resp(last_applied_manifest, observer_schema, response):
    for schema in observer_schema:
        for field in schema["fields"]:
            if field not in last_applied_manifest:
                last_applied_manifest[field] = {}
            if "array_field" in field:
                for elem in response[field]:
                    if elem not in last_applied_manifest[field]:
                        last_applied_manifest[field][elem] = {}
                    if "sub_fields" in elem:
                        update_last_applied_manifest_list_from_resp(
                            last_applied_manifest[field][elem],
                            schema["sub_fields"],
                            response[field][elem],
                        )
            elif "sub_fields" in field:
                update_last_applied_manifest_list_from_resp(
                    last_applied_manifest[field],
                    schema["sub_fields"],
                    response[field],
                )
            else:
                last_applied_manifest[field] = response[field]

def update_last_applied_manifest_list_from_resp(last_applied_manifest, observer_schema, response):
    for i, observed_field in enumerate(observer_schema):
        observed_value = response[i]
        if isinstance(observed_value, list):
            update_last_applied_manifest_list_from_resp(observed_field.value, observed_field.schema, observed_value)
        else:
            last_applied_manifest[observed_value] = observed_field.value

def update_last_applied_manifest_list_from_resp(last_applied_manifest, observer_schema, response):
    if response.startswith("null"):
        raise ValueError("Received a null response")
    elif response.startswith("[") or response.startswith("]"):
        if response.startswith("["):
            response_list = response[1:].split(",")
            for response in response_list:
                last_applied_manifest.append(update_last_applied_manifest_dict_from_resp(last_applied_manifest[-1], observer_schema, response))
        else:
            while response.endswith(']'):
                response = response[:-1]
            last_applied_manifest.pop()
    elif response.startswith("{"):
        raise ValueError("Unexpected opening curly brace")
    else:
        raise ValueError("Invalid response")
    return last_applied_manifest

def update_last_applied_manifest_dict_from_resp(last_applied_manifest, observer_schema, response):
    for field, value in response.items():
        if field in observer_schema:
            if field not in last_applied_manifest:
                last_applied_manifest[field] = {}
            update_last_applied_manifest_dict_from_resp(last_applied_manifest[field], observer_schema[field], value)
        else:
            raise KeyError('Field ' + field + ' is not present in the Kubernetes response')

def update_last_applied_manifest_dict_from_resp(last_applied_manifest, observer_schema, response):
    for field, value in observer_schema.items():
        if field in response:
            if isinstance(value, dict):
                update_last_applied_manifest_dict_from_resp(
                    last_applied_manifest[field], value, response[field])
            else:
                if field not in last_applied_manifest:
                    last_applied_manifest[field] = value
        else:
            raise KeyError(f"Observed field {field} is not present in the Kubernetes response")
    return last_applied_manifest

def update_last_applied_manifest_dict_from_resp(last_applied_manifest, observer_schema, response):
    for k, v in observer_schema.items():
        if isinstance(observer_schema[k], dict):
            update_last_applied_manifest_dict_from_resp(last_applied_manifest[k], observer_schema[k], response[k])
        elif isinstance(observer_schema[k], list):
            update_last_applied_manifest_list_from_resp(last_applied_manifest[k], observer_schema[k], response[k])
        else:
            last_applied_manifest[k] = response[k]
    return last_applied_manifest

def update_last_applied_manifest_dict_from_resp(last_applied_manifest, observer_schema, response):
    """Updates the partial `last_applied_manifest` from a partial Kubernetes response.

    Args:
        last_applied_manifest (dict): The partial `last_applied_manifest` to update.
        observer_schema (dict): The partial `observer_schema` to use for reference.
        response (dict): The partial response from the Kubernetes API.

    Raises:
        KeyError: If a required field is not present in the response.

    Returns:
        partial_manifest (dict): The updated partial `last_applied_manifest` dictionary.
    """
    partial_manifest = {}
    for field_path, field_value in response.items():
        field_name = field_path.split('.')[-1]
        if field_name in observer_schema:
            if field_name in [k for k, v in partial_manifest.items()]:
                continue
            if field_value is not None and field_name not in last_applied_manifest:
                partial_manifest[field_name] = field_value
            else:
                value = last_applied_manifest[field_name]
                partial_manifest[field_name] = value
        else:
            raise KeyError(f'{field_name} is not an observed field')
    return partial_manifest

def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    if not app.spec.manifest:
        return
    for resource in app.spec.manifest:
        if not resource.observer.schema or not resource.observer.schema.schema:
            resource.observer.schema = generate_default_resource_observer_schema(resource.kind)

def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    for resource in app.spec.manifest:
        if 'observer_schema' not in resource:
            resource['observer_schema'] = generate_default_observer_schema_for_object(resource)

def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    # Get the list of Kubernetes resource kinds present in the manifest
    kinds = set()
    for resource in app.spec.manifest:
        kinds.add(resource['kind'])

    # Iterate over the list of Kubernetes resource kinds and evaluate if an observer schema has
    # been specified for each one
    for kind in kinds:
        # If the observer schema for the current kind is not specified, generate a default one
        if kind not in app.spec.observer_schemas:
            # First, get the list of fields for the current Kubernetes resource kind
            fields = set()
            for resource in app.spec.manifest:
                if resource['kind'] == kind:
                    for key, value in resource.items():
                        if key not in {'kind', 'apiVersion'} and value is not None:
                            fields.add(key)

            # Next, generate a default observer schema with the list of fields
            default_schema = {}
            for field in fields:
                default_schema[field] = {
                    'type': 'string',
                    'default': 'kube-ops',
                    'description': 'Kubernetes {}'.format(kind),
                }

            # Finally, add the default observer schema to the list of observer schemas
            app.spec.observer_schemas[kind] = default_schema

def generate_default_observer_schema(app):
    # Iterate over the resources in the manifest
    for resource in app.spec.manifest:
        # Check if a custom observer schema has been specified for this resource
        if 'observer' not in resource.schema:
            # If not, create a default observer schema for this resource
            default_observer = {
                'schema': k8s.ObserveOptions(
                    scope=app.spec.namespace,
                    kind=resource.kind,
                    labels=resource.metadata.labels,
                    timeout='5s',
                    colors=[
                        {
                            'color': 'green',
                            'value': '<50',
                            'threshold': 100,
                        },
                    ],
                ),
            }
            # Add the default observer schema to the resource's schema
            resource.schema.observer = default_observer

def format(sql, params):
    if isinstance(params, collections.abc.Mapping):
        if isinstance(sql, str):
            pass
        else:
            sql = str(sql, params)
    elif isinstance(params, collections.abc.Sequence):
        if isinstance(sql, str):
            pass
        else:
            sql = str(sql, params)
    else:
        raise ValueError("params must be a Mapping or Sequence")
    return sql, params

