def validate(path):
    """Validate OCFL object at path or pyfs root.

    Returns True if valid (warnings permitted), False otherwise.
    """
    # Perform basic validation checks
    if not path:
        raise ValueError("Path cannot be None or empty")

    # Check if path is a valid root for OCFL object
    if not path.is_dir():
        raise ValueError("Path is not a directory")

    # Check if path contains a valid OCFL object
    if not path.glob("*.ocfl.md"):
        raise ValueError("Path does not contain a valid OCFL object")

    # Check if OCFL object is valid
    try:
        object_root = Path(path, "objects")
        if not object_root.is_dir():
            raise ValueError("OCFL object does not contain root directory 'objects'")

        for directory in object_root.iterdir():
            manifest = Path(directory, "manifest.yml")
            if not manifest.is_file():
                raise ValueError("OCFL object directory does not contain manifest file")
    except Exception as e:
        raise ValueError("OCFL object is invalid") from e

    return True

