def validate(self, inventory, extract_spec_version=False):
    """Validate a given inventory.

    If extract_spec_version is True then will look at the type value to determine
    the specification version. In the case that there is no type value or it isn't
    valid, then other tests will be based on the version given in self.spec_version.
    """

    # check for valid inventory parameter
    if not isinstance(inventory, dict):
        raise ValueError("Inventory must be a dictionary")

    # check for valid extract_spec_version parameter
    if not isinstance(extract_spec_version, bool):
        raise ValueError("extract_spec_version must be a boolean")

    # get the type value if it exists
    type_value = inventory.get("type")

    # extract the specification version
    if extract_spec_version:
        if type_value is None or not isinstance(type_value, str):
            raise ValueError("Invalid type value")
        try:
            spec_version = int(type_value[-1])
        except ValueError:
            raise ValueError("Invalid type value")
    else:
        # if extract_spec_version is False, then use the class
        # specification version instead
        spec_version = self.spec_version

    # validate the inventory based on the specification version
    if spec_version == 1:
        # validate inventory against specification version 1
        if not self._validate_inventory_version_1(inventory):
            raise ValueError("Inventory does not meet standards for version 1")
    elif spec_version == 2:
        # validate inventory against specification version 2
        if not self._validate_inventory_version_2(inventory):
            raise ValueError("Inventory does not meet standards for version 2")
    else:
        raise ValueError("Unsupported specification version")

    return inventory

def validate(self, inventory, extract_spec_version=False):
    if extract_spec_version:
        version = inventory.get('type').get('version')
        if not version:
            raise ValueError('Must specify a version in the type field')
        self.spec_version = version
    for sub_inventory in inventory.get('sub_inventories', []):
        self._validate(sub_inventory)

