        if not digests:
            raise ValueError("No digests specified")
        absent_digests = [d for d in digests if d not in self.all_digests]
        if absent_digests:
            raise ValueError("Digests {} are absent from all_digests".format(absent_digests))
        unused_digests = [d for d in digests if d not in digests_used]
        if unused_digests:
            raise ValueError("Digests {} are unused".format(unused_digests))

def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""
    # Initialize a set to store all the digests in the manifest
    manifest_digests = set()

    # Iterate over the manifest files and extract all the digests
    for manifest_file in manifest_files:
        manifest_digests.update(manifest_file.digests)

    # Iterate over the digests used in the input and check if they are present in the manifest
    for digest in digests_used:
        if digest not in manifest_digests:
            return False

    # If all the digests in the input are present in the manifest, return True
    return True

