def validate_as_prior_version(self, prior):
    if not isinstance(prior, InventoryValidator):
        raise ValueError("Input prior must be an instance of InventoryValidator")
    if self.inventory_id != prior.inventory_id:
        raise ValueError("Current inventory and prior inventory must have the same inventory ID")
    if self.version_id < prior.version_id:
        raise ValueError("Current inventory version must be greater than prior inventory version")
    if self.inventory_config_id != prior.inventory_config_id:
        raise ValueError("Current inventory config ID must be the same as prior inventory config ID")

def validate_as_prior_version(self, prior):
        if not isinstance(prior, InventoryValidator):
            raise ValueError("prior must be an InventoryValidator instance")

        if self.model_id != prior.model_id or self.item_id != prior.item_id:
            raise ValueError("prior and self have different model and item identifiers")

        if self.deposit_date <= prior.deposit_date:
            raise ValueError("prior was deposited after self")

        # Check that the inventory counts are within tolerable bounds
        if prior.get_count(self.item_id) > self.get_count(self.item_id) * 1.10:
            raise ValueError("inventory count for item_id {0} in self is not within 10% of the count in prior".format(self.item_id))

        if prior.get_count(self.item_id) < self.get_count(self.item_id) * 0.90:
            raise ValueError("inventory count for item_id {0} in self is not within 10% of the count in prior".format(self.item_id))

        # Check that the deposit dates are consistent
        if self.deposit_date != prior.deposit_date:
            raise ValueError("deposit_date in prior is different from deposit_date in self")

def validate_as_prior_version(self, prior):
    """Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object and both self and prior inventories are assumed to have been checked for internal consistency.
    """
    if not isinstance(prior, InventoryValidator):
        raise ValueError("Input must be an instance of InventoryValidator")

    for item in prior.inventory:
        if item not in self.inventory:
            raise ValueError("Item {0} present in prior inventory but not in current inventory".format(item))

    for item in self.inventory:
        if item not in prior.inventory:
            raise ValueError("Item {0} present in current inventory but not in prior inventory".format(item))

    for item in prior.inventory:
        if prior.get_item_quantity(item) != self.get_item_quantity(item):
            raise ValueError("Quantity of item {0} in current inventory is {1}, but in prior inventory it is {2}".format(item, self.get_item_quantity(item), prior.get_item_quantity(item)))

