def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    if not isinstance(fixity, dict):
        raise TypeError("fixity must be a dictionary")

    if not isinstance(manifest_files, list):
        raise TypeError("manifest_files must be a list")

    for file in fixity:
        if not file in manifest_files:
            raise ValueError("file {} is not listed in manifest".format(file))

        if not isinstance(fixity[file], dict):
            raise TypeError("Fixity for file {} must be a dictionary".format(file))

        for algorithm in fixity[file]:
            if not algorithm in ['md5', 'sha1', 'sha256', 'sha512']:
                raise ValueError("Invalid algorithm {}"
                                 "for fixity of file {}".format(algorithm, file))

            if not isinstance(fixity[file][algorithm], str):
                raise TypeError("Fixity for algorithm {} of file {}"
                                "must be a string".format(algorithm, file))

def validate_fixity(self, fixity, manifest_files):
        """
        Validate fixity block in inventory.
        Check the structure of the fixity block and makes sure that only files
        listed in the manifest are referenced.
        """
        if not isinstance(fixity, dict):
            raise ValueError("Fixity must be a dict")
        if not all(key in fixity for key in ["algorithm", "checksum"]):
            raise ValueError("Fixity block does not have all required fields")
        algorithm = fixity["algorithm"]
        checksum = fixity["checksum"]
        if algorithm not in ["md5", "sha256"]:
            raise ValueError("Algorithm must be one of: md5, sha256")
        if not isinstance(checksum, str):
            raise ValueError("Checksum must be a string")
        if not re.fullmatch(r"[0-9a-fA-F]{32}", checksum):
            raise ValueError("Checksum must be a 32-character hex string")
        for file in fixity.keys():
            if file not in manifest_files:
                raise ValueError("Unexpected file in fixity block: %s" % file)

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """

    # Check if the fixity block is a dictionary
    if not isinstance(fixity, dict):
        raise ValueError("Fixity block is not a dictionary")

    # Check if there is a "files" key in the fixity block
    files = fixity.get("files", None)
    if files is None:
        raise ValueError("Fixity block does not contain a \"files\" key")

    # Check if the "files" key is a dictionary
    if not isinstance(files, dict):
        raise ValueError("\"files\" key in fixity block is not a dictionary")

    # Check if all the files in the fixity block are listed in the manifest
    for file in files.keys():
        if file not in manifest_files:
            raise ValueError("File {} is not listed in the manifest".format(file))

    # Check if all the required keys for each file in the fixity block are present
    for file, hashes in files.items():
        required_keys = ("fixity", "hash")
        for key in required_keys:
            if key not in hashes:
                raise ValueError("Missing required key {} in fixity block for file {}".format(key, file))

