def _group_files_by_xml_filename(xml_filename, files):
    file_groups = {}
    for file in files:
        if file.endswith(".xml"):
            base_name = os.path.splitext(file)[0]
            if base_name == xml_filename:
                if base_name not in file_groups:
                    file_groups[base_name] = [file]
                else:
                    file_groups[base_name].append(file)
    return file_groups

def _group_files_by_xml_filename(xml_filename, files):
    xmls = []

    # Iterate through the files and collect the ones that match the XML patterns
    for file in files:
        if re.match(f".*_{xml_filename}_[1-9]{{2}}.xml", file):
            xmls.append(file)

    # Create a dict to store the information
    file_groups = {}

    # Iterate through the XML files, and for each one, group the files by their package name
    for xml in xmls:
        package = xml.split("_")[0]
        if package not in file_groups:
            file_groups[package] = []
        file_groups[package].append(xml)

    return file_groups

def _group_files_by_xml_filename(source, xmls, files):
    xml_filenames = set()
    for xml in xmls:
        xml_filenames.add(os.path.basename(xml))

    packages = {}
    for file in files:
        file_name = os.path.basename(file)
        if file_name in xml_filenames:
            package = {}
            for xml in xmls:
                if os.path.basename(xml) == file_name:
                    package[os.path.basename(xml)] = xml
            packages[file_name] = package

    return packages

