def _eval_file(prefix, filename, file_folder):
    file_type = None
    asset_type = None
    mimetype = 'application/octet-stream'
    if prefix == 'mipmap':
        file_type = 'mesh'
    elif prefix == 'texture':
        file_type = 'texture'
        asset_type = 'texture'
    elif prefix == 'normals':
        file_type = 'texture'
        asset_type = 'normals'
    elif prefix == 'material':
        file_type = 'material'
    elif prefix == 'screen':
        file_type = 'screen'
    elif prefix == 'model':
        file_type = 'model'
    else:
        file_type = 'unknown'

    if file_type == 'mesh':
        mimetype = 'application/gltf+json'
    elif file_type == 'texture':
        mimetype = 'image/{extension}'.format(extension=filename.split('.')[-1])
    elif file_type == 'material':
        if 'metallicRoughness' in filename:
            mimetype = 'application/gltf+json'
        elif 'specularGlossiness' in filename:
            mimetype = 'application/gltf+json'
        else:
            mimetype = 'application/json'
    elif file_type == 'screen':
        mimetype = 'application/gltf+json'
    elif file_type == 'model':
        mimetype = 'application/gltf+json'
    elif file_type == 'unknown':
        mimetype = 'application/octet-stream'

    return {
        'file_type': file_type,
        'asset_type': asset_type,
        'mimetype': mimetype,
        'prefix': prefix,
        'filename': filename,
        'file_folder': file_folder
    }

