    new_args = []
    for expr in args:
        if isinstance(expr, And):
            if isinstance(expr.left, Constant) and expr.left.value == self.value:
                new_args.append(expr.right)
            elif isinstance(expr.right, Constant) and expr.right.value == self.value:
                new_args.append(expr.left)
            else:
                new_args.append(expr)
        elif isinstance(expr, Or):
            if (isinstance(expr.left, Not) and expr.left.value.value == self.value) or
                    (isinstance(expr.right, Not) and expr.right.value.value == self.value):
                new_args += expr.values
            else:
                new_args.append(expr)
        else:
            new_args.append(expr)
    return new_args

