    """Validate storage root hierarchy.

    Args:
        validate_objects (bool, optional): Whether to validate specific objects. Defaults to True.
        check_digests (bool, optional): Whether to check object digests. Defaults to True.
        show_warnings (bool, optional): Whether to show warnings. Defaults to False.

    Returns:
        num_objects (int): number of objects checked
        good_objects (int): number of objects checked that were found to be valid

    Method steps:
    1. check_storage
        - validate storage root
        - check if storage is available
    2. check_objects
        - validate objects at root level if `validate_objects` is True
        - check if objects have valid digest if `check_digests` is True
    3. check_warnings
        - display warnings if `show_warnings` is True
    4. return num_objects and good_objects
    """
    num_objects = 0
    good_objects = 0

    if self.check_storage:
        if self.storage_root is None:
            raise RuntimeError("Storage root is not set.")
        if self.storage is None:
            raise RuntimeError("Storage root is not connected.")

    if validate_objects:
        for obj in self.storage.root:
            num_objects += 1
            if obj.validate():
                good_objects += 1

        if check_digests:
            for obj in self.storage.root:
                if not obj.has_valid_digest():
                    raise RuntimeError("Object digest is invalid.")

    if show_warnings:
        for obj in self.storage.root:
            warnings = obj.get_warnings()
            if warnings:
                print(f"Object {obj} has warnings: {warnings}")

    return num_objects, good_objects

