def next_version(version):
    if version.startswith("0"):
        version_parts = version[1:].split(".")
    else:
        version_parts = version.split(".")

    major = int(version_parts[0])
    minor = int(version_parts[1])
    patch = int(version_parts[2] if len(version_parts) > 2 else 0)

    patch += 1
    if patch > 99:
        patch = 0
        minor += 1
        if minor > 99:
            minor = 0
            major += 1
            if major > 99:
                major = 0
                minor = 0
                patch = 1

    return f"{major}.{minor}.{patch}"

def next_version(version):
    """
    Next version identifier following existing pattern.
    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    if not version:
        return "1.0.0"

    major, minor, patch = version.split(".")
    if int(patch) == 99:
        if int(minor) == 99:
            next_major = str(int(major) + 1)
            return next_major + ".0.0"
        else:
            return major + "." + str(int(minor) + 1) + ".0"
    else:
        return major + "." + minor + "." + str(int(patch) + 1)

def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    for version_dir in version_dirs:
        version_inventory_path = os.path.join(self.root_dir, version_dir, 'inventory.json')
        if not os.path.exists(version_inventory_path):
            raise ValueError(f'Inventory for version {version_dir} is missing')
        version_inventory = json.load(open(version_inventory_path))
        if 'version' not in version_inventory:
            raise ValueError(f'Inventory for version {version_dir} is missing "version" field')
        if version_inventory['version'] != version_dir:
            raise ValueError(f'Expected inventory for version {version_dir} to have version {version_dir}, but it has {version_inventory["version"]}')
        if 'contents' not in version_inventory:
            raise ValueError(f'Inventory for version {version_dir} is missing "contents" field')
        for content in version_inventory['contents']:
            if 'source' not in content:
                raise ValueError(f'Inventory for version {version_dir} is missing "source" field in content {json.dumps(content)}')
            if 'digest' not in content:
                raise ValueError(f'Inventory for version {version_dir} is missing "digest" field in content {json.dumps(content)}')
            # Store content digests in a set for easy comparison later
            self.content_digests[content['digest']] = content['source']
    return self

