        # find the first matching key
        for i, (r_key, r_value) in enumerate(result):
            if r_key.value == key.value:
                if not isinstance(r_value, ruamel.yaml.nodes.MappingNode):
                    result[i] = (key, value)
                    break
                # if the key matches and the corresponding value is a MappingNode,
                # do a deep merge of its children
                result[i] = (key, deep_merge_nodes(r_value.value, value.value))
                break
