def parse_arguments(*unparsed_arguments):
    """
    Given command-line arguments with which this script was invoked, parse the arguments and return
    them as a dict mapping from subparser name (or "global") to an argparse.Namespace instance.
    """
    parsed_arguments = {}
    argv = sys.argv[1:]
    if six.PY2:
        argv = [unicode(arg) for arg in argv]
    for arg in argv:
        if arg.startswith(b"--"):
            # If the argument starts with "--", then it is a global argument and does not
            # belong to any of the subparsers. Add it to the "global" subparser.
            subparser = "global"
        else:
            # Otherwise, try to find a subparser for the argument.
            for name, parser in self._subparsers:
                if arg in parser._option_string_actions:
                    subparser = name
                    break
            else:
                # If no subparser was found, then the argument is unrecognized.
                print("ERROR: Invalid argument {}".format(arg))
                sys.exit(1)
        namespace, args = parser.parse_known_args(argv[argv.index(arg):])
        if args:
            # If there are any remaining arguments, then there is a parsing error.
            print("ERROR: Parsing error")
            sys.exit(1)
        parsed_arguments[subparser] = namespace
    return parsed_arguments

