def paging(response, max_results):
    if max_results < 0:
        raise ValueError("max_results must be greater than or equal to 0")
    if not response:
        return
    cur_page = []
    for obj in response:
        cur_page.append(obj)
        if len(cur_page) == max_results:
            yield cur_page
            cur_page = []
    if cur_page:
        yield cur_page

def size_to_bytes(size):
    """Convert human readable file size to bytes.

    Resulting value is an approximation as input value is in most case rounded.

    Args:
        size: A string representing a human readable file size (eg: '500K')

    Returns:
        A decimal representation of file size
    """
    if not size:
        return None

    size_str = size.strip()

    # check for units
    if "K" in size_str:
        return int(size_str[:size_str.index("K")]) * 1000
    elif "M" in size_str:
        return int(size_str[:size_str.index("M")]) * 1000000
    elif "G" in size_str:
        return int(size_str[:size_str.index("G")]) * 1000000000

    # no units found, return as is
    return int(size_str)

def _dictsum(dicts):
    """
    Combine values of the dictionaries supplied by iterable dicts.

    >>> _dictsum([{'a': 1, 'b': 2}, {'a': 5, 'b': 0}])
    {'a': 6, 'b': 2}
    """

    result = {}
    for key in dicts:
        result[key] = sum(dicts[key].values())

    return result

