def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    base = len(alphabet)
    result = []
    while number > 0:
        result.append(alphabet[number % base])
        number //= base
    if padding is not None:
        result.extend(['0'] * padding)
    result.reverse()
    return ''.join(result)

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    if padding is not None and padding >= 0:
        number = str(number).zfill(padding)
    res = []
    while number > 0:
        res.append(alphabet[number % len(alphabet)])
        number //= len(alphabet)
    return "".join(res[::-1])

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    if not isinstance(number, int):
        raise TypeError("'number' must be an integer")
    if not isinstance(alphabet, List):
        raise TypeError("'alphabet' must be a list")
    if padding is not None and not isinstance(padding, int):
        raise TypeError("'padding' must be an integer or None")

    result = ""
    base = len(alphabet)
    while number > 0:
        result = alphabet[number % base] + result
        number //= base

    if padding is not None and len(result) < padding:
        result = "0" * (padding - len(result)) + result

    return result

def _replace_register(flow_params, register_number, register_value):
    """Replace value from flows to given register number

    'register_value' key in dictionary will be replaced by register number
    given by 'register_number'

    :param flow_params: Dictionary containing defined flows
    :param register_number: The number of register where value will be stored
    :param register_value: Key to be replaced by register number

    """

    for flow in flow_params.values():
        if isinstance(flow, dict):
            if register_value in flow:
                flow[register_number] = flow.pop(register_value)
        elif isinstance(flow, list):
            for idx, item in enumerate(flow):
                if isinstance(item, dict) and register_value in item:
                    item[register_number] = item.pop(register_value)
                    flow[idx] = item
    return flow_params

