def get_repo_archive(url, destination_path):
    archive_file = Path(destination_path) / "archive.tar.gz"
    with requests.get(url, stream=True) as r:
        r.raise_for_status()
        with open(archive_file, "wb") as f:
            for chunk in r.iter_content(chunk_size=8192):
                if chunk:
                    f.write(chunk)
    with tarfile.open(archive_file, "r:gz") as tar:
        for item in tar:
            if item.name.endswith(".desc"):
                desc_file = Path(destination_path) / item.name
                with open(desc_file, "wb") as f:
                    f.write(item.read())
    return destination_path

def regex_dict(item):
    matches = re.findall(r"[*|\.]", item)
    if len(matches) == 0:
        return item
    else:
        for match in matches:
            if match == "*":
                item = re.sub(r"\*", "(.*)", item)
            if match == ".":
                item = re.sub(r"\.","([^\.]*)", item)
