def lsplit(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    Args:
        s: The input string to split.
        platform: 'this' = auto from current platform;
                  1 = POSIX;
                  0 = Windows/CMD
                  (other values reserved)
    Returns:
        list: The split string elements.

    """

    if platform == 'this':
        platform = sys.platform == 'posix'
    elif platform == 1:
        platform = 'posix'
    elif platform == 0:
        platform = 'cp1252'
    else:
        raise ValueError(f'Invalid platform: {platform}')

    if platform == 'posix':
        p_regex = re.compile(r'''(?:[ \t]*(?:"[\S\[\{\}]|[^ "\t\n\[\{])[^\[\]}{]+)+|[ \t]+(?:\[[^\]]+\]|[^\s"'{}]+)+)|(?:\[[^\]]*\]|[^\s"'{}]+)''')
    elif platform == 'cp1252':
        p_regex = re.compile(r'''(?:[ \t]*(?:".*"?|[^ \t\n\[\{<])[^\[\]}{<>]+)+|[ \t]+(?:\[.*\]|[^\s"'{}]+)+)|(?:\[.*\]|[^\s"'{}]+)''')
    else:
        raise ValueError(f'Invalid platform: {platform}')

    matches = p_regex.findall(s)
    return list(matches)

def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.

    For use with subprocess, for argv injection etc. Using fast REGEX.

    Args:
        s (str): String to split.
        platform (str): String representing the platform.
            'this' (default): auto from current platform;
            1: POSIX;
            0: Windows/CMD
            (other values reserved)

    Returns:
        list: List of strings representing the split command line.
    """
    if platform == 'this':
        platform = os.name

    if platform == 'posix':
        # shlex.split() is fast enough on POSIX platforms
        return shlex.split(s)
    else:
        # Use a regular expression to split the command line on Windows
        # TODO: use character escaping for more accuracy
        return re.split(r'\s+', s)

def prepare_repository_from_archive(archive_path: str, filename: Optional[str] = None, tmp_path: Union[PosixPath, str] = "/tmp") -> str:
    """Given an existing archive_path, uncompress it.
    Returns a file repo url which can be used as origin url.

    This does not deal with the case where the archive passed along does not exist.
    """
    if not os.path.exists(archive_path):
        raise FileNotFoundError(2, "No such file or directory", archive_path)

    if not os.path.isabs(tmp_path):
        tmp_path = os.path.join(os.getcwd(), tmp_path)

    if filename is not None and len(filename) == 0:
        raise ValueError("Invalid empty filename")

    repo_url = None

    with tempfile.TemporaryDirectory(dir=tmp_path) as tmp_dir:
        try:
            subprocess.run(["tar", "-xzf", archive_path, "-C", tmp_dir], check=True)
        except subprocess.CalledProcessError as error:
            raise OSError(error.returncode, error.stderr.decode())

        repo_dir = os.path.join(tmp_dir, filename if filename else os.path.splitext(os.path.basename(archive_path))[0])

        try:
            shutil.rmtree(repo_dir)
        except FileNotFoundError:
            pass

        os.rename(tmp_dir, repo_dir)

        repo_url = f"file://{repo_dir}"

    return repo_url

