    return process.stdout.strip()

def subprocess_run_helper(func, *args, timeout=None, extra_env=None):
    """
    Run a function in a sub-process.
    """
    if not callable(func):
        raise ValueError("Argument 'func' must be a function")
    if timeout is not None and not isinstance(timeout, (int, float)):
        raise ValueError("Argument 'timeout' must be an int or float")
    if extra_env is not None and not isinstance(extra_env, dict):
        raise ValueError("Argument 'extra_env' must be a dict")

    cmd = [sys.executable, "-m", " improvement"]
    if args:
        cmd += args
    if extra_env:
        cmd += "-e", extra_env
    try:
        with subprocess.Popen(cmd, stdout=subprocess.PIPE, stderr=subprocess.PIPE,
            universal_newlines=True) as proc:
            result, error = proc.communicate(timeout) or ""
    except subprocess.CalledProcessError as err:
        result, error = "", str(err.returncode)
    if not result:
        log.error("Error running function: %s\n%s", func, error)
    return result

