def find_roots(graph: Graph, prop: URIRef, roots: Optional[Set["Node"]] = None) -> Set["Node"]:
    # Initialize the set of roots
    if roots is None:
        roots = set()

    # Iterate over all the triples in the graph
    for triple in graph:
        # If the triple matches the specified property and is not already in the set of roots
        if triple[1] == prop and triple[0] not in roots:
            # Add the subject of the triple to the set of roots
            roots.add(triple[0])

    # Return the set of roots
    return roots

def find_roots(graph, prop, roots = None):
    if roots is None:
        roots = set()
    for child, parent in graph.subject_objects(predicate=prop):
        if child not in roots and parent not in roots:
            roots.add(child)
            find_roots(graph, prop, roots)
            roots.remove(child)
    return roots

def find_roots(graph, prop, roots=None):
    if roots is None:
        roots = set()
    for triple in graph:
        if triple[1] == prop:
            if not roots == (triple[2],):
                roots.add(triple[2])
            find_roots(graph, prop, roots)
    return roots

def find_roots(graph: Graph, prop: URIRef, roots: Optional[Set[Node]] = None) -> Set[Node]:
    """
    Find the roots in some sort of transitive hierarchy.

    find_roots(graph, rdflib.RDFS.subClassOf)
    will return a set of all roots of the sub-class hierarchy

    Assumes triple of the form (child, prop, parent), i.e. the direction of
    RDFS.subClassOf or SKOS.broader

    """
    if roots is None:
        roots = set()
    for child, parent in graph.triples((None, prop, None)):
        if parent not in graph:
            roots.add(child)
        if child not in roots:
            find_roots(graph, prop, roots)
    return roots

