    configurations = {}
    parse_errors = []
    for filename in config_filenames:
        configuration = load_configuration(filename, resolve_env=resolve_env)
        if configuration is None:
            parse_errors.append(errors["filename"] + filename + "cannot be parsed")
            continue
        configurations[filename] = configuration
    if overrides is not None:
        for override, value in overrides.items():
            for _, configuration in configurations.items():
                if override in configuration:
                    configuration[override] = value
    return configurations, parse_errors

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    configs = {}
    errors = []
    for filename in config_filenames:
        try:
            config = load_config(filename, overrides, resolve_env)
        except Exception as e:
            errors.append(logging.LogRecord(level=logging.ERROR, message=str(e), name='ConfigLoader', exc_info=True))
            continue
        configs[filename] = config
    return configs, errors

