def protocol_handlers(cls, protocol_version=None):
    """ Return a dictionary of available Bolt protocol handlers,
    keyed by version tuple. If an explicit protocol version is
    provided, the dictionary will contain either zero or one items,
    depending on whether that version is supported. If no protocol
    version is provided, all available versions will be returned.

    :param protocol_version: tuple identifying a specific protocol
        version (e.g. (3, 5)) or None
    :return: dictionary of version tuple to handler class for all
        relevant and supported protocol versions
    :raise TypeError: if protocol version is not passed in a tuple
    """

    protocol_version = (protocol_version[0], protocol_version[1]) if protocol_version else ()
    protocol_handlers = {}
    for handler in cls._derived_handlers:
        try:
            if protocol_version and handler.PROTOCOL_VERSION == protocol_version:
                protocol_handlers[protocol_version] = handler
                break
        except AttributeError:
            continue
        else:
            protocol_handlers[handler.PROTOCOL_VERSION] = handler

    if not protocol_version:
        for key, value in cls.SUPPORTED_PROTOCOL_VERSIONS.items():
            if key in protocol_handlers:
                continue
            protocol_handlers[key] = value

    return protocol_handlers

def protocol_handlers(cls, protocol_version=None):
    """ Return a dictionary of available Bolt protocol handlers,
    keyed by version tuple. If an explicit protocol version is
    provided, the dictionary will contain either zero or one items,
    depending on whether that version is supported. If no protocol
    version is provided, all available versions will be returned.

    :param protocol_version: tuple identifying a specific protocol
        version (e.g. (3, 5)) or None
    :return: dictionary of version tuple to handler class for all
        relevant and supported protocol versions
    :raise TypeError: if protocol version is not passed in a tuple
    """

    protocol_handlers = {}

    if protocol_version is not None:
        if not isinstance(protocol_version, tuple):
            raise TypeError("Protocol version must be passed in a tuple")
        if protocol_version in cls._protocol_versions:
            handler_class = cls._protocol_handlers[protocol_version]
            protocol_handlers[protocol_version] = handler_class
        else:
            raise TypeError(f"Protocol version {protocol_version} not supported")
    else:
        for version, handler in cls._protocol_handlers.items():
            protocol_handlers[version] = handler

    return protocol_handlers

