def hist_to_graph(hist, make_value=None, get_coordinate="left",
                  field_names=("x", "y"), scale=None):
    if make_value is None:
        make_value = lambda bin_: bin_
    if get_coordinate == "left":
        get_coordinate = lambda bin_: bin_.left
    elif get_coordinate == "right":
        get_coordinate = lambda bin_: bin_.right
    else:
        get_coordinate = lambda bin_: (bin_.left + bin_.right) / 2
    points = [(get_coordinate(bin_), make_value(bin_)) for bin_ in hist]
    if scale is None:
        scale = hist.scale
    elif scale is True:
        scale = hist.scale
    else:
        scale = GraphScale(order=scale)
    return Graph(points, scale=scale, field_names=field_names)

def hist_to_graph(hist, make_value=None, get_coordinate="left", field_names=("x", "y"), scale=None):
    graph = Graph()
    for bin_index, bin_content in enumerate(zip(hist.bin_values, hist.edges)):
        bin_value = make_value(bin_content)  # customize with make_value
        if get_coordinate == "left":
            x_coordinate = bin_index * hist.bin_width + hist.min_x + hist.bin_width/2
        elif get_coordinate == "right":
            x_coordinate = (bin_index + 1) * hist.bin_width + hist.min_x
        elif get_coordinate == "middle":
            x_coordinate = bin_index * hist.bin_width + hist.min_x + hist.bin_width/2
        else:
            raise ValueError(f"Unknown coordinate type: {get_coordinate}")
        graph.add_point(x_coordinate, bin_value)
    if scale == True:
        graph.scale = hist.scale
    else:
        graph.scale = scale
    graph.field_names = field_names
    return graph

def _verify(iface, candidate, tentative=False, vtype=None):
    provided = getattr(candidate, "__provides__", ())
    implemented = getattr(
        candidate, "__implemented__", getattr(candidate, "__implemented_by_interface__", ())
    )
    methods = {(m, getattr(iface, m)) for m in iface.methods()}
    attributes = {(a, getattr(iface, a)) for a in iface.names()}

    if tentative:
        provided = tuple(iface.providedBy(p) for p in provided)
        implemented = tuple(iface.implementedBy(i) for i in implemented)
    else:
        provided = tuple(iface.providedBy(p) for p in provided if iface.assertProvidedByDevice(p))
        implemented = tuple(
            iface.implementedBy(i) for i in implemented if getattr(i, "__implementers__", []))

    for item in methods:
        if (
            item.name() not in implemented
            or item.code.co_argcount != getattr(item[1], "__code__").co_argcount
            or not all(item.signatures())
        ):
            raise Invalid(iface, candidate, item.name())

    for item in attributes:
        if item.name() not in implemented or not item.getter():
            raise Invalid(iface, candidate, item.name())

    return True

def _verify(iface, candidate, tentative=False, vtype=None):
    if not tentative:
        if not iface.providedBy(candidate):
            raise zope.interface.Invalid("Interface not provided by candidate")
    missing_methods = []
    for method in iface:
        if not hasattr(candidate, method.__func__.__name__):
            missing_methods.append(method)
    if missing_methods:
        raise zope.interface.Invalid("Candidate is missing methods: %r" % missing_methods)
    for method, allowed_types in iface.getMethodInfo(method).items():
        if not isinstance(candidate, allowed_types):
            raise zope.interface.Invalid("Method %s has wrong types, expected %r but got %r"
                                         % (method.__func__.__name__, allowed_types,
                                            type(candidate)))
    missing_attributes = []
    for name, attr_info in iface.namesAndDescriptions():
        try:
            candidate[name]
        except KeyError:
            missing_attributes.append(name)
    if missing_attributes:
        raise zope.interface.Invalid("Candidate is missing attributes: %r" % missing_attributes)
    return True

def verifyObject(iface, candidate, tentative=False):
    """
    Verify that *candidate* might correctly provide *iface*.

    This involves:

    - Making sure the candidate claims that it provides the
    interface using ``iface.providedBy`` (unless *tentative* is `True`,
    in which case this step is skipped). This means that the candidate's class
    declares that it `implements <zope.interface.implementer>` the interface,
    or the candidate itself declares that it `provides <zope.interface.provider>`
    the interface

    - Making sure the candidate defines all the necessary methods

    - Making sure the methods have the correct signature (to the
    extent possible)

    - Making sure the candidate defines all the necessary attributes

    :return bool: Returns a true value if everything that could be
    checked passed.
    :raises zope.interface.Invalid: If any of the previous
    conditions does not hold.

    .. versionchanged:: 5.0
        If multiple methods or attributes are invalid, all such errors
        are collected and reported. Previously, only the first error was reported.
        As a special case, if only one such error is present, it is raised
        alone, like before.
    """

    if not tentative:
        if not iface.providedBy(candidate):
            raise zope.interface.Invalid(
                "Candidate does not claim to provide the interface"
            )

    provided_methods = {
        meth.__name__
        for meth in candidate.__class__().__dict__.values()
        if isinstance(meth, types.FunctionType) and not getattr(meth, "_nobind", False)
    }
    required_methods = set(
        filter(
            lambda m: not getattr(m, "_nobind", False),
            inspect.getmembers(iface, inspect.isfunction),
        )
    )
    missing_methods = required_methods - provided_methods
    if missing_methods:
        raise zope.interface.Invalid(
            f"Candidate is missing methods {', '.join(missing_methods)}"
        )

    provided_attributes = set(candidate.__dict__)
    required_attributes = {
        attr for attr, val in inspect.getmembers(iface, lambda x: not isinstance(x, types.MethodType))
    }
    missing_attributes = required_attributes - provided_attributes
    if missing_attributes:
        raise zope.interface.Invalid(
            f"Candidate is missing attributes {', '.join(missing_attributes)}"
        )

    for method_name in required_methods:
        method = getattr(iface, method_name)
        candidate_method = getattr(candidate, method_name)
        try:
            iface.verify(method, candidate_method)
        except zope.interface.Invalid as e:
            raise zope.interface.Invalid(f"{e.args[0]} for method {method_name}")

    return True

def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    """
    if tentative:
        return True
    elif isinstance(candidate, iface):
