    elif issubclass(candidate, iface):
        return True
    else:
        return False

def verifyClass(iface, candidate):
    """
    Verify that the *candidate* might correctly provide *iface*.
    """

    if not iface in candidate.__bases__:
        raise TypeError("The candidate class does not seem to implement the given interface. Missing methods: %s" % (", ".join(set(map(repr, iface.__methods__)) - set(map(repr, candidate.__methods__)))))

    for method in iface.__methods__:
        expected_signature = iface.__methods__[method].__signature__
        actual_signature = candidate.__methods__[method].__signature__
        if expected_signature != actual_signature:
            raise TypeError("The implementation of method %s has a different signature than the expected signature. Expected signature: %s. Actual signature: %s" % (repr(iface.__methods__[method]), repr(expected_signature), repr(actual_signature)))

