def determineMetaclass(bases: list, explicit_metaclass: Type = None) -> Type:
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    if not bases:
        raise ValueError("Missing base classes for determining metaclass")

    if explicit_metaclass:
        return explicit_metaclass

    base_metaclasses = [base.__class__ for base in bases]
    if len(base_metaclasses) == 1:
        return base_metaclasses[0]

    unique_metaclasses = set(base_metaclasses)
    if len(unique_metaclasses) == 1:
        return unique_metaclasses.pop()

    raise TypeError(
        "Incompatible metaclasses for inferring metaclass, cannot derive from {bases}"
    )

def determine_metaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    if explicit_mc:
        return explicit_mc, None

    for base in bases:
        try:
            for baseobj in base.infer(context=None):
                if isinstance(baseobj, ClassDef) and baseobj.hide:
                    return baseobj._metaclass, None
        except exceptions.InferenceError:
            pass

    return None, None

