    Args:
        bases (list[object]): List of base classes for the object
        explicit_mc (class, optional): Explicit metaclass to use

    Returns:
        class: Determined metaclass

    """
    for base in bases:
        if hasattr(base, '__metaclass__') and base.__metaclass__:
            return base.__metaclass__

    if isinstance(explicit_mc, type):
        return explicit_mc

    if hasattr(type, '__metaclass__') and type.__metaclass__:
        return type.__metaclass__

    return type

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""

    bases = list(bases)
    if explicit_mc is not None:
        bases.insert(0, explicit_mc)

    for base in bases:
        try:
            mc = getattr(base, "__metaclass__")
            if not inspect.isclass(mc):
                raise MetaclassConfusion()
            return mc
        except MetaclassConfusion:
            pass
        except AttributeError:
            pass

    raise MetaclassNotFound()

