            converter.set_default_style('PAIRS')
            break
        elif parameter.style == 'RECORD':
            converter.set_default_style('RECORD')
            break
    # Set the default prefix
    prefix = self.converter_prefix
    if prefix is not None:
        converter.set_default_prefix(prefix)
    # Return the converter
    return converter

def parse(timestr, default=None, ignoretz=False, tzinfos=None, **kwargs):
    """
    Parse the date/time string into a datetime.datetime object.

    :param timestr: Any date/time string using the supported formats.
    :param default: The default datetime object, if this is a datetime object and not None, elements specified in timestr replace elements in the default object.
    :param ignoretz: If set True, time zones in parsed strings are ignored and a naive datetime.datetime object is returned.
    :param tzinfos: Additional time zone names / aliases which may be present in the string. This argument maps time zone names (and optionally offsets from those time zones) to time zones. This parameter can be a dictionary with timezone aliases mapping time zone names to time zones or a function taking two parameters (tzname and tzoffset) and returning a time zone. The timezones to which the names are mapped can be an integer offset from UTC in seconds or a datetime.tzinfo object.
    :param \\*\\*kwargs: Keyword arguments as passed to _parse().
    :return: Returns a datetime.datetime object or, if the fuzzy_with_tokens option is True, returns a tuple, the first element being a datetime.datetime object, the second a tuple containing the fuzzy tokens.
    :raises ParserError: Raised for invalid or unknown string format, if the provided tzinfo is not in a valid format, or if an invalid date would be created.
    :raises TypeError: Raised for non-string or character stream input.
    :raises OverflowError: Raised if the parsed date exceeds the largest valid C integer on your system.
    """
    if timestr is None or (not isinstance(timestr, str) and hasattr(timestr, "read")):
        raise TypeError("timestr must be a string or character stream, not " + str(timestr.__class__.__name__) + ".")
    if default and not isinstance(default, datetime.datetime):
        raise TypeError(
            "default must be a datetime.datetime instance, not " + str(default.__class__.__name__) + ".")
    if ignoretz and (tzinfos is not None):
        raise ParserError("ignoretz and tzinfos arguments are mutually exclusive.")
    if ignoretz:
        tzinfos = {"": datetime.timezone.utc}
    result_naive, result_ conceptual = _parse(timestr, tzinfos)
    if not (result_naive and result_conceptual):
        if not (default is None):
            return default
        else:
            raise ParserError("Unknown date/time string format.")
    if (default is None) or (result_conceptual != default):
        result_conceptual = result_conceptual._replace(tzinfo=result_naive.tzinfo)
        if (ignoretz and result_conceptual.tzinfo):
            raise ParserError("Time zone in input string ignored.")
        if (not ignoretz) and (not result_conceptual.tzinfo):
            raise ParserError("Missing time zone in input string and default not provided.")
    return result_conceptual

