def identify_request(request: RequestType) -> bool:
    """
    Try to identify whether this is a Matrix request

    :param request: The request to identify
    :return: True if the request is a Matrix request, False otherwise
    """
    if not request.headers.get('content-type', None) == 'application/json':
        return False
    if not request.data:
        return False
    try:
        data = json.loads(request.data)
    except json.JSONDecodeError:
        return False
    if not isinstance(data, list):
        return False
    for item in data:
        if not isinstance(item, dict):
            return False
        if not item.get('method', None) or not item.get('crypto_pubkey', None):
            return False
    return True

