def find_tags(text: str, replacer: callable = None) -> Tuple[Set, str]:
    tags = set()
    in_code_block = False
    code_block_marker = ""
    replaced_text = ""
    for line in text.splitlines():
        if "```" in line and "<CODE>" not in line:
            in_code_block = not in_code_block
            code_block_marker = "```" if in_code_block else ""
        if code_block_marker:
            replaced_text += line.replace(code_block_marker, "").strip() + "\n"
        else:
            replaced_text += line + "\n"
        for tag in re.findall(r"#<(\S+)>", line):
            tags.add(tag)
            if replacer:
                replaced_text = replaced_text.replace(f"#{tag}>", f"{replacer(tag)}")
    return tags, replaced_text

def process_text_links(text):
    """Process links in text, adding some attributes and linkifying textual links."""
    def linkify(text):
        def convert(match):
            href = match.group(0)
            return f'<a href="{href}" target="_blank">{href}</a>'
        return re.sub(r'(?i)\b((?:https?://|www\d{0,3}[.]|[a-z0-9.\-]+[.][a-z]{2,4}/)(?:[^\s()<>]+|\(([^\s()<>]+|(\([^\s()<>]+\)))*\))+(?:\(([^\s()<>]+|(\([^\s()<>]+\)))*\)|[^\s`!()\[\]{};:'".,<>?«»“”‘’]))', convert, text)
    def add_attrs(text):
        return f'<a href="{text}" target="_blank" rel="noopener noreferrer"`"nofollow">{text}</a>'
    return linkify(add_attrs(text))

def process_text_links(text):
  """Process links in text, adding some attributes and linkifying textual links."""
  import re
  from urllib.parse import urlparse

  # define regular expression for linkifying text quotes (URLs)
  link_regex = re.compile(r'http[s]?://(?:[a-zA-Z]|[0-9]|[$-_@.&+]|[!*\(\),]|(?:%[0-9a-fA-F][0-9a-fA-F]))+')

  # define regular expression for matching text quotes (URLs)
  match_regex = re.compile(r'([a-zA-Z]+:\/\/[a-zA-Z0-9.-_?=/]+)')

  # define regular expression for removing parentheses from links
  remove_parens_regex = re.compile(r'\(([a-zA-Z]+:\/\/[a-zA-Z0-9.-_?=]+)\)')

  # define function to replace URL links with HTML link tags
  def replace_link(match):
    url = match.group(1)
    try:
      parsed_url = urlparse(url)
    except:
      return match.group(0)
    else:
      return '<a href="{}" target="_blank">{}</a>'.format(url, parsed_url.netloc)

  # define function to remove parentheses from links
  def remove_parens(match):
    return match.group(1)

  # replace URL links with HTML link tags
  text = link_regex.sub(replace_link, text)

  # remove parentheses from links
  text = remove_parens_regex.sub(remove_parens, text)

  return text

def process_text_links(text):
    # Initialize a dictionary to store link text to URL mappings
    links = {}
    # Iterate over the text to find all URL links and store them in the dictionary
    for link in re.findall(r"http[s]?://\S+", text):
        links[link] = link
    # Iterate over the text again to find all file references and store them in the dictionary
    for link in re.findall(r"\S+\.\S+", text):
        links[link] = link.replace(" ", "%20")
    # Return the processed text with all links converted to markdown format
    return re.sub(r"\[.+\]\(.+\)", lambda m: "[{}]({})".format(m.group(0), links[m.group(0)]), text)

def process_text_links(text):
    """Process links in text, adding some attributes and linkifying textual links."""

    # Check if the text is not None
    if text is None:
        return text

    # Check if the text contains any URL or file references
    if not re.findall(r"(http\S+)|\b\w+\.\w+\b", text):
        return text

    # Convert textual URLs to links
    text = re.sub(r"(http\S+)", r'<a target="_blank" href="\1">\1</a>', text)

    # Convert file references to links
    for file_path in re.findall(r"\b\w+\.\w+\b", text):
        if os.path.exists(file_path):
            text = re.sub(file_path, '<a target="_blank" href="{0}">{0}</a>'.format(file_path), text)

    # Return the processed text
    return text

