    else:
        raise ValueError("Error retrieving NodeInfo document")

def get_nodeinfo_well_known_document(url, document_path=None):
    try:
        parsed_url = urlparse(url)
        if not parsed_url.scheme or not parsed_url.netloc:
            raise ValueError("Invalid url")
        if document_path and not document_path.startswith("/"):
            document_path = "/" + document_path
        elif not document_path:
            document_path = "/.well-known/nodeinfo"
        return {
            "version": "1.1",
            "server": {
                "baseUrl": parsed_url.geturl(),
                "name": parsed_url.netloc,
                "software": "Diaspora/1.0",
            },
            "protocols": ["diaspora"],
            "services": {"inbound": [], "outbound": []},
            "openRegistrations": False,
        }
    except Exception as e:
        raise ValueError("Invalid url or document path") from e

