def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    :param document: The webfinger document string
    :return: A dictionary containing the parsed webfinger data
    """
    try:
        parsed_json = json.loads(document)
    except (json.JSONDecodeError, TypeError):
        parsed_json = {"type": "XRD"}
        for vCard in xrd.Diaspora.vcard(document):
            if vCard.type == "XRD":
                for element in vCard.sub_elements():
                    if element.local_name == "Subject":
                        parsed_json["Subject"] = element.text
                    elif element.local_name == "Property":
                        parsed_json[element.property] = element.content
                    elif element.local_name == "Alias" and element.property == "rel":
                        parsed_json["aliases"] = element.content
    return parsed_json

def parse_diaspora_webfinger(document: str) -> Dict:
    import json
    import xml.etree.ElementTree as ET

    webfinger = {}

    # Check if document is in JSON format
    try:
        webfinger = json.loads(document)
    except json.JSONDecodeError:
        pass

    # Check if document is in XRD format
    if not webfinger:
        try:
            root = ET.fromstring(document)
            webfinger = {
                "channels": root.find('.//*[@type="http://schemas.gtalk.google.com/xsrf-channel"]').get("href")
            }
        except:
            return None

    # Parse additional properties
    for channel in webfinger.get("channels"):
        webfinger[channel["type"]] = channel["href"]

    return webfinger

def parse_diaspora_webfinger(document: str) -> Dict:
    if not isinstance(document, str):
        raise TypeError("parse_diaspora_webfinger() expects a string")

    # Try parsing the document as JSON
    try:
        return json.loads(document)
    except json.JSONDecodeError:
        pass

    # If parsing as JSON fails, try parsing as XRD
    try:
        r = ElementTree.fromstring(document)
    except ElementTree.ParseError:
        raise ValueError("Invalid Diaspora webfinger document")

    # Get the XRD element
    xrd = r.find("{http://docs.oasis-open.org/ns/xri/xrd-1.0}XRD")
    if xrd is None:
        raise ValueError("XRD element not found in Diaspora webfinger document")

    # Get the first entry element
    entry = xrd.find("{http://docs.oasis-open.org/ns/xri/xrd-1.0}Link/{http://docs.oasis-open.org/ns/xri/xrd-1.0}ProviderID")
    if entry is None:
        raise ValueError("ProviderID element not found in Diaspora webfinger document")

    # Convert the string to a dict
    d = {}
    for e in entry:
        d[e.tag] = e.text

    return d

