def send_document(url, data, timeout=10, method="POST", *args, **kwargs):
    headers = CaseInsensitiveDict({
        'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; WOW64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/91.0.4472.124 Safari/537.36'
    })
    if method.lower() == 'post':
        response = requests.post(url, data=data, timeout=timeout, headers=headers, *args, **kwargs)
    elif method.lower() == 'get':
        response = requests.get(url, data=data, timeout=timeout, headers=headers, *args, **kwargs)
