        raise ValueError(f"Unsupported method '{method}', supported methods are 'POST' and 'GET')
    return response

def send_document(url, data, timeout=10, method="POST", *args, **kwargs):
    try:
        if method == method.upper():
            requests.post(url, data=data, timeout=timeout, *args, **kwargs)
            return (response.status_code, None)
        else:
            requests.get(url, param=data, timeout=timeout, *args, **kwargs)
            return (response.status_code, None)
    except requests.exceptions.HTTPError as e:
        logger.debug("send_document: exception {}" , e)
        return (None, e)

def dict_insert(dic, val, key, *keys):
    if not keys:
        dic[key] = val
    else:
        dic.setdefault(key, {}).update({keys[0]: dict_insert(dic[key], val, *keys[1:])})

def list_of_file_names(settings_dirs, spec_option):
    """Return a list of fully qualified names of files in the given directories, with the specified option.

    Args:
        settings_dirs (list): list of directories to search for files in.
        spec_option (str): option to specify the type of files to search for.

    Returns:
        list: a list of fully qualified names of files in the given directories, with the specified option.
    """
    file_names = []
    for d in settings_dirs:
        if not os.path.isdir(d):
            continue
        for f in os.listdir(d):
            if fnmatch.fnmatch(f, '*.py') and f.endswith(spec_option):
                file_names.append(os.path.join(d, os.path.dirname(f)))
    return file_names

