def validate_from_content(cls, spec_content=None):
    if spec_content is None:
        return {}
    spec = yaml.safe_load(spec_content)
    # check if spec has all required fields
    for key, field in cls.schema.items():
        if field.get('required') and key not in spec:
            raise IRValidatorException(f"Mandatory field {key} is missing in spec file")
    return spec

def validate_from_content(cls, spec_content=None):
    data = yaml.load(spec_content, Loader=Loader)
    if not cls.has_required_fields(data, spec):
        raise IRValidatorException("Mandatory data is missing in spec")
    return data

def validate_from_file(cls, yaml_file=None):
    if not yaml_file:
        raise ValueError("Please provide a path to a YAML file")
    data = {"samples": []}
    with open(yaml_file) as f:
        yaml_data = yaml.load(f)
        for sample in yaml_data:
            required_fields = ["id", "value", "run_id"]
            for required_field in required_fields:
                if not sample.get(required_field):
                    raise IRValidatorException(f"Mandatory field {required_field} missing in file")
            data["samples"].append(sample)
    return data

def validate_from_file(cls, yaml_file):
        """Loads & validates that a YAML file has all required fields

        :param yaml_file: Path to YAML file
        :raise IRValidatorException: when mandatory data is missing in file
        :return: Dictionary with data loaded from a YAML file
        """
        with yaml_file.open() as f:
            data = yaml.load(f)

        if all(cls.MANDATORY_KEYS):
            for key in cls.MANDATORY_KEYS:
                if key not in data:
                    raise IRValidatorException(f"Key '{key}' is missing in the YAML file")
            return data
        else:
            raise IRValidatorException(f"YAML file does not contain all mandatory fields")

def validate_from_file(yaml_file):
    if not os.path.isfile(yaml_file):
        raise FileNotFoundError(f"{yaml_file} not found.")

    with open(yaml_file, 'r') as f:
        data = yaml.load(f)

    for field in cls.required_fields:
        if field not in data:
            raise IRValidatorException(f"Mandatory field {field} missing in {yaml_file}.")

    return data

def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files. """
    for k, v in parser_dict.items():
        if "include" in v:
            v = {**v, ** _include_groups(v.pop("include"))}
        parser_dict[k] = v
    return parser_dict

def _include_groups(parser_dict):
    if 'include' in parser_dict:
        for include_group in parser_dict['include']:
            parser_dict = {**parser_dict, **include_group}
    return parser_dict

def _include_groups(self, parser_dict):

    """Resolves the include dict directive in the spec files. """

    include_dict = parser_dict.get('include')
    if not include_dict:
        return

    for include_file in include_dict:
        include_data = self._load_file(include_file)
        parser_dict.update(include_data)

    for include_group in include_dict['groups']:
        group_name = include_group['name']

        group = parser_dict['groups'][group_name]
        item_list = group['items']

        include_group = include_dict['groups'][group_name]
        for item in include_group['items']:
            item_list.append(item)

    for item in parser_dict['items']:
        if item.get('group') in include_dict['groups']:
            item['resolve'] = True

    return parser_dict

def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files. """
    if 'includes' in parser_dict:
        included = parser_dict.pop('includes')
        for group_name, group_data in iteritems(included):
            parser_dict[group_name] = group_data
    return parser_dict

def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files. """
    for group_key, group_values in iteritems(parser_dict):
        if group_key == 'includes':
            for include_group in group_values:
                group_dict = self._parse_group(include_group)
                self._include_groups(group_dict)

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources. """
    spec_defaults = {}
    for arg in self.args:
        if arg.default not in (NO_DEFAULT, None):
            spec_defaults[arg.name] = arg.default
        elif arg.default is NO_DEFAULT and self.spec is not None:
            spec_defaults[arg.name] = self.spec.get(arg.name, NO_DEFAULT)
        elif self.config is not None:
            spec_defaults[arg.name] = self.get_config_default(arg.name)
    return spec_defaults

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources."""
    defaults = {}
    for arg in self.spec.elements:
        if arg.default is not NoDefault:
            defaults[arg.name] = arg.default
        elif isinstance(arg, arg_function_type):
            defaults[arg.name] = arg.get_default_value(self)
        elif isinstance(arg, arg_dict_type):
            args = (arg for arg in self.elements if arg.name in arg.keys)
            args = [arg.get_default_value(self) for arg in args]
            defaults[arg.name] = dict(zip(arg.keys, args))
    return defaults

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources. """
    spec_defaults = {}
    spec_configs = set()
    for arg, val in self.spec:
        if not isinstance(arg, _BaseOpt):
            continue
        if not isinstance(arg.default, NoDefault):
            spec_defaults[arg.name] = arg.default
        if arg.config:
            spec_configs.add(arg.config)

    # resolve defaults from config if provided
    if spec_configs:
        for conf in spec_configs:
            defaults = conf.get_defaults()
            for name, val in defaults:
                if not isinstance(name, _BaseOpt):
                    continue
                if name.name not in spec_defaults:
                    spec_defaults[name.name] = val

    # resolve defaults from other sources
    for src in self.sources:
        defaults = src.get_defaults()
        for name, val in defaults:
            if name not in spec_defaults:
                spec_defaults[name] = val

    return spec_defaults

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources"""
    # Resolve arguments' values from Spec and other sources
    args_to_resolve = [arg.name for arg in self.args if arg.default is NoDefault]
    if not args_to_resolve:
        return

    # Get the list of sources to resolve the unresolved arguments
    resolve_sources = [self.spec] + (self.other_sources if self.other_sources else [])

    if not resolve_sources:
        return

    # Resolve the unresolved arguments from the specified sources
    reg = re.compile(r'\$\((?P<key>\w+)\)')
    for arg_name in args_to_resolve:
        for source in resolve_sources:
            if arg_name not in source:
                continue
            source_value = source[arg_name]
            if source_value is not missing:
                try:
                    value = reg.sub(lambda m: source[m.group('key')], source_value)
                    self.args[arg_name].default = value
                    break
                except KeyError:
                    pass
    # Finally return the resolved arguments
    return [self.args[arg_name].default for arg_name in args_to_resolve]

def get_spec_defaults(self, spec):
    """Resolve arguments' values from spec and other sources. """
    defaults = {}
    for arg in spec.args:
        if not isinstance(arg, (Option, HelpOption)):
            continue
        default = arg.default
        if isinstance(default, NoDefault):
            default = arg.default
        elif isinstance(default, DynamicDefaultCallable):
            default = default()
        elif isinstance(default, DynamicDefaultAsyncCallable):
            default = await default()
        defaults[arg.name] = default
    return defaults

