def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """
    if len(args) < 1:
        raise TypeError("at least one argument is required")
    if len(args) > 2:
        raise TypeError("only one or two arguments are allowed")
    if len(args) == 1:
        if not isinstance(args[0], numbers.Real):
            raise TypeError("first argument must be a real number")
    elif len(args) == 2:
        if not (isinstance(args[0], numbers.Real) and isinstance(args[1], numbers.Real)):
            raise TypeError("both arguments must be real numbers")
        if args[0] > args[1]:
            raise ValueError("first argument must be less than or equal to second argument")
    return args

def validate_min_max_args(self, args):
    # Check if all arguments are present
    if len(args) < 2:
        raise ValueError("Expected at least 2 arguments, got " + str(len(args)))

    # Get the minimum and maximum values
    min_val = args[0]
    max_val = args[1]

    # Check if the minimum value is less than or equal to the maximum value
    if min_val > max_val:
        raise ValueError("Minimum value must be less than or equal to the maximum value")

    # Check if all values are between the minimum and maximum values
    for arg in args[2:]:
        if arg < min_val or arg > max_val:
            raise ValueError("All values must be between " + str(min_val) + " and " + str(max_val))

    # If all the values are valid, return True
    return True

def validate_min_max_args(self, args):
    min_value = self.min_value if hasattr(self, "min_value") else None
    max_value = self.max_value if hasattr(self, "max_value") else None
    if min_value is not None and max_value is not None and min_value > max_value:
        raise ValueError("Minimum value cannot be greater than the maximum value")
    if min_value is not None and len(args) < min_value:
        raise TypeError("Expected at least {} arguments, got {}".format(min_value, len(args)))
    if max_value is not None and len(args) > max_value:
        raise TypeError("Expected at most {} arguments, got {}".format(max_value, len(args)))
    return args

def validate_min_max_args(self, args):
    for arg in args:
        value = arg.value
        if arg.min_value is not None and value < arg.min_value:
            raise ValueError(f"Argument '{arg.name}' must have a value greater than or equal to {arg.min_value} but has a value of {value}")
        if arg.max_value is not None and value > arg.max_value:
            raise ValueError(f"Argument '{arg.name}' must have a value less than or equal to {arg.max_value} but has a value of {value}")
    return args

def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """

    if len(args) != 2:
        raise ValueError("Expected two arguments, received {}".format(len(args)))

    min_val, max_val = args

    if min_val >= max_val:
        raise ValueError("Minimum value must be less than maximum value")

    return min_val <= args[0] <= max_val and min_val <= args[1] <= max_val

def create_complex_argumet_type(self, subcommand, type_name, option_name, spec_option):
    """Build the complex argument type

    :param subcommand: the command name
    :param type_name: the complex type name
    :param option_name: the option name
    :param spec_option: option's specifications
    :return: the complex type instance
    """

    class ComplexArgumentType(metaclass=ABCMeta):
        @abstractmethod
        def __init__(self, option_name, subcommand):
            self.option_name = option_name
            self.subcommand = subcommand
            self.type_name = None

        @abstractmethod
        def __str__(self):
            return f"<{self.type_name} {self.option_name} {self.subcommand}>"

        @abstractmethod
        def get_type_name(self):
            return self.type_name

    class ComplexArgumentTypeWithSpec(ComplexArgumentType):
        def __init__(self, option_name, subcommand, spec_option):
            super().__init__(option_name, subcommand)
            self.spec_option = spec_option

        def __str__(self):
            return f"<{self.type_name} {self.option_name} {self.subcommand} {self.spec_option}>"

        def get_type_name(self):
            return self.type_name

    class ComplexArgumentTypeNoSpec(ComplexArgumentType):
        def __init__(self, option_name, subcommand):
            super().__init__(option_name, subcommand)

        def __str__(self):
            return f"<{self.type_name} {self.option_name} {self.subcommand}>"

        def get_type_name(self):
            return self.type_name

    if spec_option:
        return ComplexArgumentTypeWithSpec(option_name, subcommand, spec_option)
    else:
        return ComplexArgumentTypeNoSpec(option_name, subcommand)

