    if extra_vars:
        if not isinstance(extra_vars, list):
            raise ValueError("Unable to merge extra-vars: List expected")
        for var in extra_vars:
            if var not in vars_dict:
                vars_dict[str(var)] = {}
            else:
                vars_dict[str(var)].update({})
    return vars_dict

def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend ``vars_dict`` with ``extra_vars``

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars
    """
    if extra_vars is not None:
        if isinstance(extra_vars, list):
            for key in extra_vars:
                if isinstance(key, dict):
                    vars_dict.update(key)
        else:
            raise ValueError("`extra_vars` must be a list")
    return vars_dict

def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend ``vars_dict`` with ``extra-vars``

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars
    """
    if vars_dict is None:
        return extra_vars
    if extra_vars is None:
        return vars_dict

    extended_vars = {**vars_dict, **extra_vars}
    return extended_vars

def merge_extra_vars(vars_dict, extra_vars=None):
    if not extra_vars:
        return vars_dict

    if not vars_dict:
        vars_dict = {}

    for var in extra_vars:
        if var not in vars_dict:
            vars_dict[var] = extra_vars[var]

    return vars_dict

def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None,
                     extra_vars=None, ansible_args=None):
    """Wraps the 'ansible-playbook' CLI.

     :param ir_workspace: An Infrared Workspace object represents the active
     workspace
     :param ir_plugin: An InfraredPlugin object of the current plugin
     :param playbook_path: the playbook to invoke
    """

    if verbose:
        verbosity = ["-vvvvv" if verbose == "DEBUG" else "-v"]

    if extra_vars:
        if not isinstance(extra_vars, dict):
            raise TypeError("extra_vars must be a dict.")
        for key in extra_vars:
            if not isinstance(key, str):
                raise TypeError("extra_vars keys must be strings.")
        extra_vars = ",".join(["=".join((key, extra_vars[key]))
                               for key in sorted(extra_vars)])
    else:
        extra_vars = ""

    if ansible_args:
        if not isinstance(ansible_args, dict):
            raise TypeError("ansible_args must be a dict.")
        for key in ansible_args:
            if not isinstance(key, str):
                raise TypeError("ansible_args keys must be strings.")
        ansible_args = ",".join(["=".join((key, ansible_args[key]))
                               for key in sorted(ansible_args)])
    else:
        ansible_args = ""

    # check that workspace has a settings file
    try:
        settings = ir_workspace.settings
    except AttributeError:
        raise TypeError("ir_workspace must have a settings attribute.")

    if not isinstance(settings, dict):
        raise TypeError("workspace settings must be a dict.")

    # load the ansible version if specified in the plugin call
    ansible_version = getattr(ir_plugin, "ansible_version", None)
    if ansible_version:
        if not isinstance(ansible_version, str):
            raise TypeError("ansible_version must be a str.")
        ansible_bin = "{0} -m ansible_module -v {1}"\
        .format(ansible_version, playbook_path)
    else:
        ansible_bin = "ansible_module -vvvv {}".format(playbook_path)

    command = [
        ansible_bin,
        " ".join(verbosity),
        "--playbook", playbook_path,
        "--extra-vars", extra_vars,
        "--tags", ",".join(tags),
        "--ansible-args", ansible_args
    ]

    logging.debug("Executing Ansible call `%s`", " ".join(command))
    p = subprocess.Popen(command)
    # FIXME: logic to wait for ansible to finish?
    stdout, stderr = p.communicate()

    if p.returncode != 0:
        # FIXME: parse error codes
        raise RuntimeError("Ansible reported an error when executing playbook {}".format(playbook_path))

    return output

def _convert_non_cli_args(self, parser_name, values_dict):
    parser = getattr(self, parser_name)
    for opt in parser.options:
        if opt.flag:
            continue
        default_value = parser.get_default(opt.name)
        if opt.user_optional and values_dict.get(opt.name) == parser.get_default(opt.name) and default_value is not None:
            values_dict[opt.name] = opt.convert(default_value)
        if opt.name in values_dict and values_dict[opt.name] != parser.get_default(opt.name):
            values_dict[opt.name] = opt.convert(values_dict[opt.name])

def _convert_non_cli_args(self, parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """

    if parser_name == "virsh":
        # Convert the "force" argument to bool
        if "force" in values_dict and isinstance(values_dict["force"], str):
            values_dict["force"] = str2bool(values_dict["force"])

        # Convert the "nvram" argument to int
        if "nvram" in values_dict and isinstance(values_dict["nvram"], str):
            values_dict["nvram"] = int(values_dict["nvram"])

    elif parser_name == "ospd":
        # Convert the "enabled" argument to bool
        if "enabled" in values_dict and isinstance(values_dict["enabled"], str):
            values_dict["enabled"] = str2bool(values_dict["enabled"])

        # Convert the "max_backups" argument to int
        if "max_backups" in values_dict and isinstance(values_dict["max_backups"], str):
            values_dict["max_backups"] = int(values_dict["max_backups"])

    # Convert all other arguments to strings
    for key, value in values_dict.items():
        if key != "force" and key != "nvram" and key != "enabled" and key != "max_backups":
            values_dict[key] = str(value)

    return values_dict

