            "choices": ["python", "python2"]
        }],
        [["-p", "--port"], {
            "help": "Used as a fallback port if one is not provided",
            "action": "store",
            "nargs": "-1",
            "type": "int",
            "default": [8080]
        }],
        [["-u", "--user"], {
            "help": "No subprocess user",
            "action": "store",
            "nargs": "-1",
            "default": [""]
        }],
    ]

    def extend_args(arg_parser, cli_options):
        for name, arg_kw in cli_options:
            arg_parser.add_argument(name, kwargs=arg_kw)

    extend_args(root_subparsers, cli_options)

def strip_root(path, root):
    """Removes the root from the given path, throwing an exception on failure."""

    return path.strip(root)

def strip_root(path, root):
    """Remove root from path, throw exception on failure."""
    if not path.startswith(root):
        raise Exception("Path does not start with root")
    return path[len(root):]

def strip_root(path, root):
    if not path.startswith(root):
        raise ValueError("Path does not start with root")
    return path.replace(root, "")

def strip_root(path, root):
    if os.path.commonpath([path, root]) == root:
        return path[len(root)+1:]
    raise FoundationsError('Path is not under root: {0}'.format(root))
